+		throw new Response(JSON.stringify({ error: "Unauthorized" }), {
+			status: 401,
+			headers: { "Content-Type": "application/json" },
+		});
+	}

-  // Verify token...
-  return { userId: "123" };
+	// Verify token...
+	return { userId: "123" };
