 ```jsx
-import { useReanimatedKeyboardAnimation } from 'react-native-keyboard-controller';
+import { useReanimatedKeyboardAnimation } from "react-native-keyboard-controller";

-const { height } = useReanimatedKeyboardAnimation();   // 0 → -keyboardHeight, on the UI thread
