 	const hasAnySocialProviders =
 		(githubClientId && githubClientSecret) || (googleClientId && googleClientSecret);

 	// Determine rpID and origin for passkey
 	const getRpID = (originUrl?: string) => {
 		if (originUrl) {
 			try {
 				const url = new URL(originUrl);
 				return url.hostname;
 			} catch {
 				return "localhost";
 			}
 		}
 		return "localhost";
