  <ThemeProvider value={...}>
    <AnimatedSplashOverlay />
    <Stack screenOptions={{ headerShown: false }} />
    {!isPending && !session && <Redirect href="/sign-in" />}
    {!isPending && session && <Redirect href="/" />}
